"""Independent public EVM-check vector, generated by Python eth-account/eth-utils."""
import json
from pathlib import Path
from eth_account import Account
from eth_account.messages import encode_defunct
from eth_utils import keccak

password = 'test check password'
key = keccak(text=password)
check = bytes.fromhex('11' * 32)
redeemer = '0x' + '22' * 20
message = keccak(check + bytes.fromhex(redeemer[2:]))
signed = Account.sign_message(encode_defunct(primitive=message), key)
vector = dict(password=password, address=Account.from_key(key).address.lower(),
              check='0x' + check.hex(), redeemer=redeemer,
              message='0x' + message.hex(), digest='0x' + signed.message_hash.hex(),
              signature='0x' + signed.signature.hex())
(Path(__file__).resolve().parents[1] / 'tests' / 'checks-vectors.json').write_text(
    json.dumps(vector, indent=2) + '\n', newline='\n')
